// Code generated by xgen. DO NOT EDIT.
// Source: xgen/screens/src/authoring/blocks/signup.ts
/**
 * A whole sign-in page: the AuthCard placed in the page. Axes: layout (split: a picture panel beside the card,
 * centered: the card on a tinted page, minimal: the card alone in a narrow column), side (end, start: the side
 * of the picture), mode, social. The page's heading is the card's title.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Container } from "../primitives/container/container";
import { Grid } from "../primitives/grid/grid";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { AuthCard } from "../blocks/auth-card";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { AuthSwitch, AuthVisual } from "./auth-layout.types";
import type { AuthLabels } from "./auth-card.types";

export type AuthLayoutProps = {
  id: string;
  title: string;
  text: string;
  submit: string;
  switchTo: AuthSwitch;
  labels: AuthLabels;
  visual: AuthVisual;
  level?: 1 | 2;
  layout?: "split" | "centered" | "minimal";
  side?: "end" | "start";
  mode?: "signin" | "signup" | "reset" | "magic";
  social?: "none" | "show" | "first";
  landmarkLabel?: string;
};

export function AuthLayout({
  id,
  title,
  text,
  submit,
  switchTo,
  labels,
  visual,
  level = 1,
  layout = "split",
  side = "end",
  mode = "signin",
  social = "none",
  landmarkLabel,
}: AuthLayoutProps) {
  return (
    <Block tag="div" className="w-full" data-testid="auth-layout" data-layout={layout}>
      <Container className={cn("mx-auto w-full max-w-6xl px-4", "py-12")} data-slot="container">
        {((layout as string) === "split") ? (
          <Grid cols="1-2" className="items-stretch gap-8">
            <Box className="mx-auto flex w-full max-w-sm items-center">
              <AuthCard
                id={id}
                title={title}
                text={text}
                submit={submit}
                switchText={switchTo.text}
                switchLink={switchTo.link}
                switchHref={switchTo.href}
                labels={labels}
                mode={mode}
                layout="plain"
                social={social}
                level={level}
                landmarkLabel={landmarkLabel}
              />
            </Box>
            <Stack
              gap="4"
              align="stretch"
              className={cn(
                "justify-end rounded bg-muted p-8",
                (((side as string) === "start") ? "md:order-first" : "md:order-last")
              )}
              data-testid="visual"
            >
              <MediaFrame alt={visual.title} ratio="4/3" />
              <Title as={2} size="2xl" weight="bold">
                {visual.title}
              </Title>
              <Text size="sm" className="text-muted-foreground">
                {visual.text}
              </Text>
            </Stack>
          </Grid>
        ) : ((layout as string) === "centered") ? (
          <Box className="mx-auto w-full max-w-md rounded bg-muted p-6">
            <AuthCard
              id={id}
              title={title}
              text={text}
              submit={submit}
              switchText={switchTo.text}
              switchLink={switchTo.link}
              switchHref={switchTo.href}
              labels={labels}
              mode={mode}
              social={social}
              level={level}
              landmarkLabel={landmarkLabel}
            />
          </Box>
        ) : (
          <Box className="mx-auto w-full max-w-sm">
            <AuthCard
              id={id}
              title={title}
              text={text}
              submit={submit}
              switchText={switchTo.text}
              switchLink={switchTo.link}
              switchHref={switchTo.href}
              labels={labels}
              mode={mode}
              layout="plain"
              social={social}
              level={level}
              landmarkLabel={landmarkLabel}
            />
          </Box>
        )}
      </Container>
    </Block>
  );
}

// Code generated by xgen. DO NOT EDIT.
